#!/usr/bin/env python3
"""Detached restart helper. Specs are generated by the authenticated service."""
from __future__ import annotations
import json
import os
from pathlib import Path
import signal
import subprocess
import sys
import time
from urllib.request import urlopen
from urllib.error import HTTPError

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))
from web.services.yaml_io import atomic_write
from core.processes import process_exited
from core.maintenance_work import restart_gate, MaintenanceSuperseded


def perform(path: Path):
    # This helper is freshly loaded even when the running app predates a fix.
    spec = json.loads(path.read_text())
    try:
        if spec['action'] in ('restart', 'shutdown'):
            with restart_gate(Path(spec['state_dir']), expected_runtime=spec['runtime']):
                _perform_idle(path)
        else:
            _perform_idle(path)
    except Exception as exc:
        spec.update(status='interrupted' if isinstance(exc, MaintenanceSuperseded) else 'failed',
                    error=str(exc)[:500], updated=time.time())
        if isinstance(exc, MaintenanceSuperseded):
            spec.update(superseded=True, superseded_by_runtime=exc.runtime)
        atomic_write(str(path), json.dumps(spec, ensure_ascii=False))
        atomic_write(str(Path(spec['state_dir']) / 'assistant_maintenance.json'), json.dumps(spec, ensure_ascii=False))


def _perform_idle(path: Path):
    spec = json.loads(path.read_text())
    runtime = spec['runtime']
    state = Path(spec['state_dir'])
    def save(**updates):
        spec.update(updates, updated=time.time())
        atomic_write(str(path), json.dumps(spec, ensure_ascii=False))
        atomic_write(str(state / 'assistant_maintenance.json'), json.dumps(spec, ensure_ascii=False))
    try:
        time.sleep(1)  # Let the submitting response and its receipt leave HTTP.
        old_pid = spec['pid']
        if runtime['pid'] != old_pid or old_pid <= 1 or old_pid == os.getpid():
            raise ValueError('维护进程归属验证失败')
        current = json.loads((state / 'app_runtime.json').read_text())
        if current.get('pid') != old_pid or current.get('instance_id') != runtime.get('instance_id'):
            raise ValueError('研究端实例已变更，未向旧 PID 发送信号；请核对当前服务')
        try:
            os.kill(old_pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        end = time.monotonic() + 45
        while time.monotonic() < end:
            if process_exited(old_pid):
                break
            time.sleep(0.25)
        else:
            raise RuntimeError('旧服务未能正常退出；未强制终止，也未启动重复服务')
        if spec['action'] == 'shutdown':
            save(status='completed', message='原 Web 服务已退出；网关仍可由下一次访问唤醒应用')
            return
        from scripts.gateway import _env_file_keys, _OPERATOR_OWNED
        env = {k: v for k, v in os.environ.items() if k not in _env_file_keys(ROOT) or k in _OPERATOR_OWNED}
        env['AI_RESEARCH_WEB_CONFIG'] = runtime['config_path']
        env['AI_RESEARCH_APP_PORT'] = str(runtime['port'])
        log_path = state / 'maintenance' / (spec['id'] + '-server.log')
        with log_path.open('ab') as log:
            child = subprocess.Popen([runtime['python'], str(ROOT / 'run_web.py'), 'serve', '--host', runtime['host'], '--port', str(runtime['port'])],
                                     cwd=str(ROOT), env=env, stdin=subprocess.DEVNULL, stdout=log, stderr=log,
                                     start_new_session=True)
        save(status='starting', new_pid=child.pid)
        end = time.monotonic() + 180
        url = f'http://127.0.0.1:{runtime["port"]}/api/health'
        while time.monotonic() < end:
            try:
                with urlopen(url, timeout=2) as response:
                    body = json.load(response)
                current = json.loads((state / 'app_runtime.json').read_text())
                if current.get('pid') != old_pid and body.get('instance_id') == current.get('instance_id'):
                    save(status='completed', actual=current, health=body['status'])
                    return
            except (OSError, ValueError, HTTPError):
                pass
            if child.poll() is not None:
                raise RuntimeError('新服务提前退出，请查看维护日志')
            time.sleep(1)
        raise RuntimeError('服务尚未通过健康验证，请查看维护日志和实际监听状态')
    except Exception as exc:
        save(status='failed', error=str(exc)[:500])


if __name__ == '__main__':
    perform(Path(sys.argv[1]))
